contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);
        require(collectAmount > 0);
        require(collectAmount >= c.MinSum());

        // Setup: deposit so that the sender's c-balance is depositAmount.
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Precondition ensuring the collect will definitely be attempted.
        require(c.balances(address(this)) == depositAmount);
        require(collectAmount < depositAmount);

        uint beforeBalance = address(this).balance;
        uint beforeCollectBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted ||
            (c.balances(address(this)) == beforeCollectBalance - collectAmount &&
             address(this).balance == beforeBalance + collectAmount));
    }

    receive() external payable {}
}

