pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount, uint256 collectAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount >= c.MinSum());
        try c.Deposit{value: depositAmount}() {} catch { return; }
        depositAmount = c.balances(address(this));
        vm.assume(collectAmount < depositAmount);
        uint beforeBalance = address(this).balance;
        uint256 beforeCollectBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeCollectBalance = __r; } catch { return; }
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted ||
            (c.balances(address(this)) == beforeCollectBalance - collectAmount &&
             address(this).balance == beforeBalance + collectAmount));
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount) public {
        _run(depositAmount, collectAmount);
    }

    receive() external payable {}
}
